function totalPrice(price, qty) {
  return price * qty
}
function applyDiscount(price, percent) {
  return price - price * percent / 100
}
function isWeekend(day) {
  if (day === "Saturday" || day === "Sunday") {
    return true
  }
  return false
}
function addStock(current, incoming) {
  return current + Number(incoming)
}
const cleanPhone = (phone) => phone.trim().replaceAll(" ", "")
